WITH filtered_customers AS (SELECT * FROM customers WHERE name LIKE 'Gr%' OR LOWER(email) LIKE '%ran%'), customers_stats AS (SELECT segment, CASE WHEN credit_limit >= 16500 THEN 'high' WHEN credit_limit >= 5100 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, MIN(age) AS min_age, ROUND(AVG(age), 2) AS avg_age FROM filtered_customers GROUP BY segment, CASE WHEN credit_limit >= 16500 THEN 'high' WHEN credit_limit >= 5100 THEN 'mid' ELSE 'low' END) SELECT segment, credit_limit_bucket, min_age, avg_age FROM customers_stats ORDER BY segment DESC, min_age DESC, credit_limit_bucket LIMIT 10
